// Generated by Autopus-ADK. Do not edit: `auto update` rewrites this file.
//
// The Claude Code Stop hooks for omp: when the lead agent finishes a run,
// `auto verify stop` and `auto verify language` judge the work tree and the
// replies of that run. A block is sent back as a follow-up message, so the
// agent continues with the reason, exactly once per finished run.
import { spawn } from "node:child_process"

const CHECKS: string[] = __AUTOPUS_STOP_CHECKS__
const TIMEOUT_MS = 10 * 60 * 1000

type Decision = { decision?: string; reason?: string; systemMessage?: string }

// replyTexts returns the assistant text of the run that just ended. The
// event carries the whole session, so the run starts after the last user
// message: the prompt, or this gate's own follow-up.
function replyTexts(messages: unknown): string[] {
  if (!Array.isArray(messages)) return []
  let start = 0
  for (let i = messages.length - 1; i >= 0; i--) {
    if (messages[i]?.role === "user") {
      start = i + 1
      break
    }
  }
  const texts: string[] = []
  for (const message of messages.slice(start)) {
    if (message?.role !== "assistant") continue
    const content = message.content
    if (typeof content === "string") {
      texts.push(content)
      continue
    }
    if (!Array.isArray(content)) continue
    for (const part of content) {
      if (part?.type === "text" && typeof part.text === "string" && part.text.trim() !== "") texts.push(part.text)
    }
  }
  return texts
}

function runCheck(check: string, payload: string, cwd: string): Promise<Decision> {
  return new Promise((resolve) => {
    let out = ""
    let child
    try {
      child = spawn("auto", ["verify", check], { cwd, stdio: ["pipe", "pipe", "ignore"] })
    } catch {
      resolve({})
      return
    }
    const timer = setTimeout(() => child.kill("SIGKILL"), TIMEOUT_MS)
    child.stdout.on("data", (chunk) => (out += chunk))
    child.on("error", () => {
      clearTimeout(timer)
      resolve({})
    })
    child.on("close", () => {
      clearTimeout(timer)
      try {
        resolve(JSON.parse(out.trim() || "{}"))
      } catch {
        resolve({})
      }
    })
    child.stdin.end(payload)
  })
}

export default function autopusStopGate(pi) {
  // A run that started from this gate's own follow-up is the answer to it:
  // it is checked with stop_hook_active set, so a misjudged reply costs one
  // retry, never a loop.
  let answering = false

  pi.on("agent_end", async (event, ctx) => {
    if (event?.willContinue === true || ctx?.agentKind === "sub") return
    if (process.env.AUTOPUS_VERIFY_STOP === "off" && process.env.AUTOPUS_LANGUAGE_STOP === "off") return
    const replies = replyTexts(event?.messages)
    const cwd = typeof ctx?.cwd === "string" ? ctx.cwd : process.cwd()
    const payload = JSON.stringify({
      session_id: ctx?.sessionManager?.getSessionId?.() ?? "",
      cwd,
      stop_hook_active: answering,
      last_assistant_message: replies.length > 0 ? replies[replies.length - 1] : "",
      turn_replies: replies,
    })
    answering = false
    const reasons: string[] = []
    for (const check of CHECKS) {
      const result = await runCheck(check, payload, cwd)
      if (result.decision === "block" && result.reason) reasons.push(result.reason)
      else if (result.systemMessage) ctx?.ui?.notify?.(result.systemMessage, "warning")
    }
    if (reasons.length === 0) return
    answering = true
    try {
      await pi.sendUserMessage(reasons.join("\n\n"), { deliverAs: "followUp" })
    } catch {
      answering = false
    }
  })
}
